detect_good.source:
def detect_good(code: str) -> str:
    try:
        tree = ast.parse(code)
        has_good = any(node.keyword.args[0].id == 'good' for node in ast.walk(tree) if isinstance(node, ast.Call) and node.keyword)
        return f"Good usage detected: {'Yes' if has_good else 'No'}"
    except (AttributeError, IndexError):
        return "No 'good' keyword usage found"

