def detect_good_v2(code: str) -> str:
    try:
        tree = ast.parse(code)
        good_indicators = 0
        for node in ast.walk(tree):
            if isinstance(node, (ast.ClassDef, ast.FunctionDef)):
                if node.decorator_list and any(d.id == 'property' for d in node.decorator_list):
                    good_indicators += 1
                if isinstance(node, ast.FunctionDef) and node.name.startswith('is_') or node.name.startswith('has_'):
                    good_indicators += 1
            elif isinstance(node, ast.If) and node.test and isinstance(node.test, ast.Name) and node.test.id == 'DEBUG':
                good_indicators += 1
        return f"Good patterns: {good_indicators} (e.g., properties, is_/has_ methods, DEBUG guards)"
    except:
        return "No good patterns detected (parsing error)"
